import { TestBed, ComponentFixture } from '@angular/core/testing';
import { AppComponent } from '../app/app.component';
import { LoginComponent } from '../app/user/components/login/login.component';
import { AuthService } from '../app/sections/services/auth.service';
import { HttpClientTestingModule } from '@angular/common/http/testing';
import { ReactiveFormsModule } from '@angular/forms';
import { BooksListComponent } from '../app/books/components/books-list/books-list.component';

describe('AppComponent', () => {
  beforeEach(async () => {
    await TestBed.configureTestingModule({
      declarations: [AppComponent],
    }).compileComponents();
  });

  it('should create the app', () => {
    const fixture = TestBed.createComponent(AppComponent);
    const app = fixture.componentInstance;
    expect(app).toBeTruthy();
  });

  it('should render the main page component', () => {
    const fixture = TestBed.createComponent(AppComponent);
    fixture.detectChanges();
    const compiled = fixture.nativeElement as HTMLElement;
    expect(compiled.querySelector('user-main-page')).toBeTruthy();
  });
  describe('AuthService', () => {
    let service: AuthService;

    beforeEach(() => {
      TestBed.configureTestingModule({
        imports: [HttpClientTestingModule],
        providers: [AuthService],
      });
      service = TestBed.inject(AuthService);
    });

    it('should be created', () => {
      expect(service).toBeTruthy();
    });

    it('should return false if not authenticated', () => {
      localStorage.removeItem('accessToken');
      expect(service.isAuthenticated()).toBeFalsy();
    });
  });

  describe('LoginComponent', () => {
    let component: LoginComponent;
    let fixture: ComponentFixture<LoginComponent>;

    beforeEach(async () => {
      await TestBed.configureTestingModule({
        imports: [ReactiveFormsModule],
        declarations: [LoginComponent],
      }).compileComponents();

      fixture = TestBed.createComponent(LoginComponent);
      component = fixture.componentInstance;
      fixture.detectChanges();
    });

    it('should create the login component', () => {
      expect(component).toBeTruthy();
    });

    it('should have a form with email and password fields', () => {
      expect(component.loginForm.contains('email')).toBeTruthy();
      expect(component.loginForm.contains('password')).toBeTruthy();
    });
  });

  describe('BooksListComponent', () => {
    let component: BooksListComponent;
    let fixture: ComponentFixture<BooksListComponent>;

    beforeEach(async () => {
      await TestBed.configureTestingModule({
        declarations: [BooksListComponent],
      }).compileComponents();

      fixture = TestBed.createComponent(BooksListComponent);
      component = fixture.componentInstance;
      fixture.detectChanges();
    });

    it('should create', () => {
      expect(component).toBeTruthy();
    });
  });
});
